entries[128617] = { ["name"] = "Formel: Handschuhe - Kräuterkunde der Verheerten Inseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Kräuterkunde der Verheerten Inseln' durchführt.\nHandschuhe dauerhaft verzaubern, sodass die Geschwindigkeit des Kräutersammelns auf den Verheerten Inseln und Argus erhöht wird.\nBenötigt Verzauberkunst der Verheerten Inseln (1)" }
