entries[128620] = { ["name"] = "Formel: Handschuhe - Vermessung der Verheerten Inseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Vermessung der Verheerten Inseln' durchführt.\nHandschuhe dauerhaft verzaubern, sodass die Geschwindigkeit der archäologischen Untersuchung auf den Verheerten Inseln erhöht wird.\nBenötigt Verzauberkunst der Verheerten Inseln (1)" }
entries[128621] = { ["name"] = "Formel: Verzauberter Kessel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen verzauberten Kessel herstellt.\nStellt einen verzauberten Kessel her.\nBenötigt Verzauberkunst der Verheerten Inseln (1)\n\nVerzauberter Kessel\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren verzauberten Kessel beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Chaoskristall (5), Leylichtsplitter (20), Arkhana (50), Infernoschwefel (10)" }
entries[128622] = { ["name"] = "Formel: Verzauberte Fackel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine verzauberte Fackel herstellt.\nStellt eine verzauberte Fackel her.\nBenötigt Verzauberkunst der Verheerten Inseln (1)\n\nVerzauberte Fackel\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure verzauberte Fackel beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Chaoskristall (5), Leylichtsplitter (20), Arkhana (50), Teufelswurz (10)" }
entries[128623] = { ["name"] = "Formel: Verzauberter Stift", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen verzauberten Stift herstellt.\nStellt einen verzauberten Stift her.\nBenötigt Verzauberkunst der Verheerten Inseln (1)\n\nVerzauberter Stift\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren verzauberten Stift beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Chaoskristall (5), Leylichtsplitter (20), Arkhana (50), Teufelsbalg (10)" }
entries[128625] = { ["name"] = "Formel: Leylichtkohlenpfanne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Leylichtkohlenpfanne herstellt.\nStellt eine Leylichtkohlenpfanne her.\nBenötigt Verzauberkunst der Verheerten Inseln (1)\n\nLeylichtkohlenpfanne\nSpielzeug\nBenutzen: Baut eine verzauberte Kohlenpfanne auf, die die Willenskraft aller in der Nähe um 4 erhöht und das Kochen ermöglicht. (5 Min Abklingzeit)\nBenötigt Chaoskristall , Arkhana (100), Blut von Sargeras (5)" }
entries[128630] = { ["name"] = "Altmetall", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[128632] = { ["name"] = "Wilder Schneeball", ["text"] = "Benutzen: Werft einen Schneeball mit einem kleinen Stein darin. Verursacht 0 körperlichen Schaden.\n\"Es scheint sich ein kleiner Stein darin zu befinden.\"\nVerkaufspreis:" }
entries[128634] = { ["name"] = "Mysteriöses Gebräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Magischer Schaum hüllt das anvisierte Gruppenmitglied in ein Bierlementarkostüm.\n5 Aufladungen" }
entries[128636] = { ["name"] = "Endothermischer Strahler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Beschert Freund und Feind Schnee mit Eurem großartigen neuen Schneebläser!\nWährend des Winterhauchfests ist die Abklingzeit verringert. (30 Min Abklingzeit)\n\"Mei, einfach umwerfend!\"" }
