entries[128642] = { ["name"] = "Schiff: Truppentransporter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein riesiges Schiff für Truppen- und Gütertransporte. Kann für Marinemissionen eingesetzt werden.\"" }
entries[128643] = { ["name"] = "Edelkostümset: \"Todesschwinge\"", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verkleidet Euch als Todesschwinge. (10 Sek. Abklingzeit)\n50 Aufladungen\n\"Eine aufwendige Replik Neltharions in Menschengestalt - inklusive aufblasbarem Streitkolben!\"" }
entries[128644] = { ["name"] = "Stab der Verwandlung - Modriges Geschöpf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verkleidet das anvisierte Gruppenmitglied als modriges Geschöpf.\n5 Aufladungen" }
