entries[128646] = { ["name"] = "Stab der Verwandlung - Neruber", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verkleidet das anvisierte Gruppenmitglied als Neruber.\n5 Aufladungen" }
entries[128647] = { ["name"] = "Sprudelnder Apfelwein", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Wärmender Apfelwein heilt Euch um 25% Gesundheit und erhöht für 30 Min. Eure Gewandtheit um 10% sowie Eure Größe.\n\nGewandtheit gestattet es Euch, schneller Ressourcen zu sammeln. (5 Min Abklingzeit)" }
entries[128648] = { ["name"] = "Gelber Schneeball", ["text"] = "Benutzen: Werft mich!\n\"Nicht zum Verzehr geeignet.\"\nVerkaufspreis:" }
entries[128649] = { ["name"] = "Illusion: Klauen des Winters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Waffenillusionsvorlage 'Klauen des Winters'.\nVerkaufspreis:" }
entries[128650] = { ["name"] = "Kostüm: \"Wonniges Wichtelchen\"", ["text"] = "Benutzen: Verkleidet Euren mopsigen Streuner." }
entries[128651] = { ["name"] = "Handliche Kleintierkanone", ["text"] = "Questgegenstand\nBenutzen: Feuert mehrere Kleintiere in ein Rudel Eiszahnwölfe, um sie auseinanderzutreiben.\n\"Eine Waffe mit weitem Lauf, die mehrere Kleintiere in die Luft schleudern kann.\"" }
