entries[128654] = { ["name"] = "Alards Fluxus", ["text"] = "Wird beim Aufheben gebunden\n\"Alards feinster Fluxus. Findet ausschließlich bei den exotischsten Erzen Verwendung.\"" }
entries[128655] = { ["name"] = "Hase", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Klein genug, um als Munition in der handlichen Kleintierkanone zu dienen.\"" }
entries[128658] = { ["name"] = "Schaurige Vorräte", ["text"] = "Wird an Kriegsmeute gebunden\n\"Kann bei der Veranstaltungskoordinatorin Eurer Garnison eingelöst werden.\"" }
entries[128659] = { ["name"] = "Festliche Vorräte", ["text"] = "Wird an Kriegsmeute gebunden\n\"Kann bei der Veranstaltungskoordinatorin Eurer Garnison eingelöst werden.\"" }
entries[128660] = { ["name"] = "Ghulgewand", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Kleidet die Wachen Eurer Garnison in festliche Kostüme.\"" }
entries[128661] = { ["name"] = "Schlotterglimmen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Kürbisse, Kerzen und ähnliche Dekoration für Eure Garnison.\"" }
entries[128662] = { ["name"] = "Einladung an den Seher", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Lädt einen Seher der Arakkoa in Eure Garnison ein.\"" }
entries[128663] = { ["name"] = "Brauhexenbräu", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Eine Pandarenbrauhexe, die reichlich frisches Bräu in Eure Garnison bringt.\"" }
entries[128664] = { ["name"] = "Gruselige Kriecher", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Eine schaurige Kiste voller spektraler Ratten, Maden und Spinnen.\"" }
entries[128665] = { ["name"] = "Wirrlichterkugel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Ein festliches Arrangement von Lichtern und Kränzen.\"" }
entries[128666] = { ["name"] = "Importierte Bäume", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Eine festliche Auswahl an Bäumen und Geschenken.\"" }
entries[128667] = { ["name"] = "Kleine Helfer", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Winterhauchhelfer und ein Winterwundervolt.\"" }
entries[128668] = { ["name"] = "Festtagsgarderobe", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Kleidet Eure Garnisonswachen den Festtagen entsprechend.\"" }
entries[128669] = { ["name"] = "Alte Kiste mit Dekoration", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Mit Rechtsklick Eure Garnison mit diesem Dekorationspaket schmücken.\n\"Eine Auswahl an Zuckerstangen, Mistelzweigen und Strümpfen.\"" }
entries[128670] = { ["name"] = "Wildes Geschenk", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[128671] = { ["name"] = "Diener von Grumpus", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nDiener von Grumpus : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Niemand weiß genau, wann die Legende von Grumpus in Draenor entstand, doch seine Spielzeuge sind einfach grässlich.\"\nWeltereignis:\nWinterhauchfest" }
entries[128673] = { ["name"] = "Dämonenodemtiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"In diesem Topf kann man gefahrlos mächtige Teufelsreagenzien zusammenmischen.\"" }
entries[128674] = { ["name"] = "Mallorybürette", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Art Bürette, die der Alchemist Mallory erfunden hat, wurde so kalibriert, dass man Flüssigkeiten mit großer Präzision abmessen kann.\"" }
entries[128675] = { ["name"] = "Stimmungsbombe", ["text"] = "Questgegenstand\nBenutzen: Jagt die wertlosen Geschenke von Grumpus hoch, mit einer Bombe voller Festtagsstimmung... und Vernichtung. (5 Sek. Abklingzeit)" }
entries[128676] = { ["name"] = "Unkalibrierte Mallorybürette", ["text"] = "Questgegenstand\nEinzigartig\n\"Mit dieser Bürette kann man Flüssigkeiten nicht genau abmessen.\"" }
entries[128679] = { ["name"] = "Doppelwandiger Dämonenodemtiegel", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Beschichtung dieses Tiegels wurde restauriert, aber man muss sie anscheinend noch härten.\"" }
entries[128680] = { ["name"] = "Verderbte Wurzelprobe", ["text"] = "Questgegenstand\n\"Eine Probe verderbten Wurzelholzes des großen Baumes Shaladrassil.\"" }
entries[128681] = { ["name"] = "Brüchiger Dämonenodemtiegel", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser Topf wurde hergestellt, um darin mächtige Teufelsreagenzien zusammenzumischen, aber er muss wohl ein wenig verstärkt werden.\"" }
entries[128687] = { ["name"] = "Königliche Vorladung", ["text"] = "Questgegenstand\nBenutzen: Lest mich.\n\"Mit dem Siegel von König Anduin Wrynn versehen.\"" }
entries[128690] = { ["name"] = "Aschenmauljunges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n80 ( 80)" }
entries[128692] = { ["name"] = "Königliche Vorladung", ["text"] = "Questgegenstand\nBenutzen: Lest mich.\n\"Mit dem Siegel von Kriegshäuptling Sylvanas Windläufer versehen.\"" }
entries[128693] = { ["name"] = "Seekarte Draenors", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Karte von Draenors Meeren, die minutiös mit arkanen Symbolen und seemännischen Notizen beschrieben wurde.\"" }
entries[128697] = { ["name"] = "Ketten des Widerstandes", ["text"] = "Questgegenstand" }
entries[128703] = { ["name"] = "Rad der Seelenstärke", ["text"] = "Questgegenstand" }
entries[128704] = { ["name"] = "Kursrute", ["text"] = "Questgegenstand" }
entries[128705] = { ["name"] = "Dunkelmondkartenset: Herrschaft", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nAnlegen: Erhöht den kritischen Trefferwert um 5 bis 11 . Die Höhe des kritischen Trefferwerts ist von der obenliegenden Karte des Kartensets abhängig.\nAnlegen: Mischt im Kampf regelmäßig das Kartenset.\nVerkaufspreis:" }
entries[128706] = { ["name"] = "Erhabener Himmelsschrecken", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren erhabenen Himmelsschrecken oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ungehindert durch die Grenzen der Welt unter ihm lässt die superleichte Ausrüstung dieses chromatischen Rylaks ihn mühelos durch die Wolken schießen und dahingleiten.\"\nErfolg:\nPfadfinder von Draenor" }
entries[128707] = { ["name"] = "Späherbericht: Azsuna", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Einzelheiten über die Erkundungstätigkeiten in Azsuna.\"" }
entries[128708] = { ["name"] = "Gemauserte Feder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Erhöht die Bewegungsgeschwindigkeit 30 Sek. lang um 100%. Funktioniert nicht bei Spielercharakteren über Stufe 49. (3 Sek. Abklingzeit)" }
entries[128709] = { ["name"] = "Dunkelmondkartenset: Höllenfeuer", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Erhöht den kritischen Trefferwert um 5 bis 11 . Die Höhe des kritischen Trefferwerts ist von der obenliegenden Karte des Kartensets abhängig.\nAnlegen: Mischt im Kampf regelmäßig das Kartenset.\nVerkaufspreis:" }
entries[128710] = { ["name"] = "Dunkelmondkartenset: Verheißung", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Verringert die Grundmanakosten Eurer Zauber um 3 bis 12 . Die Höhe der Manakostenverringerung ist von der obenliegenden Karte des Kartensets abhängig.\nAnlegen: Mischt im Kampf regelmäßig das Kartenset.\nVerkaufspreis:" }
entries[128711] = { ["name"] = "Dunkelmondkartenset: Unsterblichkeit", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nAnlegen: Erhöht Rüstung um 6 bis 17 . Die Höhe der Rüstung ist von der obenliegenden Karte des Kartensets abhängig.\nAnlegen: Mischt im Kampf regelmäßig das Kartenset.\nVerkaufspreis:" }
entries[128712] = { ["name"] = "Dunkelmond-Karte der Legion", ["text"] = "\"Eine zufällige Dunkelmond-Karte der Legion. Sammelt das ganze Set, um eine Belohnung zu erhalten.\"" }
