entries[128745] = { ["name"] = "Saris' Hammer", ["text"] = "Questgegenstand\n\"Der Hammer des legendären Schmieds Saris Flinkhammer.\"" }
entries[128746] = { ["name"] = "Saris' Aufzeichnungen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Kompendium aller Studien von Saris Flinkhammer zur Verarbeitung von Leystein.\"" }
entries[128747] = { ["name"] = "Späherbericht: Val'sharah", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Einzelheiten über die Erkundungstätigkeiten in Val'sharah.\"" }
entries[128748] = { ["name"] = "Späherbericht: Hochberg", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Einzelheiten über die Erkundungstätigkeiten auf dem Hochberg.\"" }
entries[128749] = { ["name"] = "Späherbericht: Sturmheim", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Einzelheiten über die Erkundungstätigkeiten in Sturmheim.\"" }
entries[128751] = { ["name"] = "Rabenwehrbrustplatte", ["text"] = "Questgegenstand\n\"Eine unglaublich widerstandsfähige Brustplatte, die aus dem gleichen Gestein besteht wie die Rabenwehr.\"" }
entries[128752] = { ["name"] = "Seelenkammer", ["text"] = "Questgegenstand\n\"Ein zerbrechlicher Kristall, der einen Dämon gefangen halten kann.\"" }
entries[128753] = { ["name"] = "Schädel des Herumkommandierens", ["text"] = "Questgegenstand\n\"Kobolde verwenden Schädel, um ihren Anspruch als Anführer zu unterstreichen.\"" }
entries[128754] = { ["name"] = "Gelbe Kerze", ["text"] = "Questgegenstand\n\"Die Kerze brennt mit gelber Flamme.\"" }
entries[128755] = { ["name"] = "Grüne Kerze", ["text"] = "Questgegenstand\n\"Die Kerze brennt mit grüner Flamme.\"" }
entries[128756] = { ["name"] = "Oenias Schädel", ["text"] = "Questgegenstand" }
entries[128757] = { ["name"] = "Adlereier", ["text"] = "Questgegenstand\n\"Ein empfindliches Gelege aus Adlereiern.\"" }
entries[128758] = { ["name"] = "Gefleckte Düsterkappe", ["text"] = "Questgegenstand\n\"Schmeckt köstlich, ist in großen Mengen jedoch tödlich.\"" }
entries[128759] = { ["name"] = "Schimmernde Pollen", ["text"] = "Questgegenstand\n\"Schimmern und glänzen in jedem Licht.\"" }
entries[128760] = { ["name"] = "Adlerei", ["text"] = "Questgegenstand\n\"Ein großes, aber dennoch empfindliches Ei eines großen Adlers vom Hochberg.\"" }
entries[128761] = { ["name"] = "Azsunianische Oliven", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 2125 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[128762] = { ["name"] = "Denkstättengebinde", ["text"] = "Benutzen: Legt einige Blumen ab um zu zeigen, dass Euer Herz berührt ist. (30 Min Abklingzeit)\nVerkaufspreis:" }
entries[128763] = { ["name"] = "Würziger Vrykulgamalost", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 4250 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Sie sagen, mit der Zeit wird er 'besser'.\"\nVerkaufspreis:" }
entries[128764] = { ["name"] = "Saftiger Azsunafeta", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Er hat eine wunderbar cremige Textur.\"\nVerkaufspreis:" }
entries[128765] = { ["name"] = "Hammer von Khaz'goroth", ["text"] = "Questgegenstand\n\"Dieses Titanenrelikt pulsiert vor Energie.\"" }
entries[128767] = { ["name"] = "Ronos' Spitzhacke", ["text"] = "Questgegenstand\nBenutzen: Entfernt das Erz behutsam aus dem Fels und hinterlässt dabei nur sehr wenig Schutt.\n\"Diese Spitzhacke wurde aus dem Sand der Küste von Azsuna gefertigt und ist leicht, aber auch zerbrechlich. Lasst große Vorsicht walten, wenn Ihr sie benutzt.\"" }
entries[128768] = { ["name"] = "Zuckerstange", ["text"] = "Benutzen: Iss mich!" }
entries[128769] = { ["name"] = "Vom Glas befreiter Leystein", ["text"] = "Questgegenstand\n\"Sorgfältig abgebauter Leystein.\"" }
entries[128770] = { ["name"] = "Grumpling", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n80 ( 80)" }
entries[128771] = { ["name"] = "Von Bernfäule befallenes Geweih", ["text"] = "Questgegenstand\n\"Das Geweih eines Eisenhornelchs, das von der Bernfäule befallen ist.\"" }
entries[128772] = { ["name"] = "Ast des Runenwalds", ["text"] = "Questgegenstand\nBenutzen: Kanalisiert die Macht des Runenwalds, um einen geschwächten ruhelosen Vorfahren wieder zur Erde zurückkehren zu lassen. (5 Sek. Abklingzeit)" }
entries[128773] = { ["name"] = "Bärenlende", ["text"] = "Questgegenstand\n\"Ein besonders dickes Steak, das viel Kraft spendet und sich daher bei Jägern großer Beliebtheit erfreut.\"" }
entries[128774] = { ["name"] = "Schwarzkehles Schwanz", ["text"] = "Questgegenstand\n\"Dieser große Schwanz verspricht eine Menge saftiges Makrurafleisch.\"" }
entries[128775] = { ["name"] = "Mal des Cenarius", ["text"] = "Questgegenstand\n\"Eine kleine Münze, in die das Emblem von Cenarius eingraviert wurde.\"" }
entries[128776] = { ["name"] = "Roter Holzschlitten", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt Euch auf einen Schlitten, der von anderen Spielercharakteren gezogen werden kann, oder setzt Euer Kampfhaustier darauf und zieht ihn selbst!\n\nFunktioniert nur bei Haustieren, die kämpfen können. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[128777] = { ["name"] = "Erhitzter Leysteinbarren", ["text"] = "Questgegenstand\n\"Findet in speziellen Projekten für Alard Schmied Verwendung.\"" }
entries[128778] = { ["name"] = "Machtsteinkristall", ["text"] = "Questgegenstand\n\"Dieser merkwürdige Kristall ist darauf vorbereitet, magische Eigenarten zu beherbergen.\"" }
