entries[128793] = { ["name"] = "Sack voller Spinnen", ["text"] = "Einzigartig (20)\nBenutzen: Wirft den Sack und lässt die Spinnen darin frei. (5 Sek. Abklingzeit)\n\"Warum solltet Ihr das behalten?\"\nVerkaufspreis:" }
entries[128794] = { ["name"] = "Sack mit spektralen Spinnen", ["text"] = "Spielzeug\nBenutzen: Wirft den Sack und lässt die Spinnen darin frei. (5 Min Abklingzeit)\n\"Bringt immer neue spektrale Spinnen hervor.\"\nVerkaufspreis:" }
entries[128801] = { ["name"] = "Modifizierter Machtsteinkristall", ["text"] = "Questgegenstand\n\"Die Kristallmatrix wurde von den Navarrogg modifiziert, um eine verheerende Wirkung auf Drogbarrituale zu entfalten.\"" }
entries[128803] = { ["name"] = "Wilde Tasche der Kooperation", ["text"] = "Wird beim Aufheben gebunden\n\"Randvoll mit Gold, Verstärkungsrunen und Ausrüstungsmarken.\"\n<Zum Öffnen rechtsklicken>" }
entries[128805] = { ["name"] = "Teufelsschutztrank", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Eine wirkungsvolle Mixtur, die sämtlichen erlittenen Schaden 10 Min. lang um 10% verringert. Funktioniert nicht bei Spielercharakteren über Stufe 49. (3 Sek. Abklingzeit)" }
entries[128807] = { ["name"] = "Münze der vielen Gesichter", ["text"] = "Spielzeug\nBenutzen: Werdet zu jemand anderem.\nWährend der Schlotternächte ist die Abklingzeit verringert. (1 Tag Abklingzeit)\nVerkaufspreis:" }
entries[128808] = { ["name"] = "Fangklaue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stangenwaffe\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nSturm Artefakt Relikt Slot\nEisen Artefakt Relikt Slot\n\nKlassen: Jäger\nAnlegen: Gewährt die Fähigkeit 'Zorn des Adlers', die eine Reihe unerbittlicher frontaler Speerstöße entfesselt.\n\"Der Adlerspeer. Speer der Wilden Götter. Fangklaue. Diese legendäre Waffe trägt viele Namen und viele Segen.\"\nVerkaufspreis:" }
entries[128809] = { ["name"] = "Neuer Rekrut", ["text"] = "Questgegenstand\nEinzigartig\n\"Hochlord Mograine bringt einen unserer Ritter mit, doch wer ist es?\"" }
entries[128810] = { ["name"] = "Glas mit Spinnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein faszinierendes Exemplar!\"" }
entries[128813] = { ["name"] = "Teufelsenergiekern", ["text"] = "Questgegenstand\n\"Ein pulsierender, von Teufelsenergie erfüllter Kern.\"" }
entries[128814] = { ["name"] = "Trank der feigen Flucht", ["text"] = "Verkaufspreis:" }
entries[128819] = { ["name"] = "Schicksalshammer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nFeuer Artefakt Relikt Slot\nEisen Artefakt Relikt Slot\n\nKlassen: Schamane\nAnlegen: Gewährt Euch den Zauber 'Schicksalswinde', durch den Ihr 'Windzorn' auf Eure Gegner niedergehen lasst.\n\"Ein Fremder wird den Hammer erheben und durch ihn wird die Gerechtigkeit walten.\"\nVerkaufspreis:" }
entries[128820] = { ["name"] = "Felo'melorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\nErhöht Eure Tempowertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nFeuer Artefakt Relikt Slot\nArkan Artefakt Relikt Slot\n\nKlassen: Magier\nAnlegen: Gewährt die Fähigkeit 'Phönixflammen', die zerstörerisches Feuer auf alle Gegner in der Nähe Eures Ziels schleudert.\n\"...keine elfischen Waffen. Nicht, wenn sie mit Magie und Hass und einer brennenden Begierde nach Rache neu geschmiedet wurden. Nein, Arthas. Felo'melorn ist stärker als je zuvor. So wie auch ich. - Kael'thas Sonnenwanderer\"\nVerkaufspreis:" }
entries[128821] = { ["name"] = "Ursocs Klauen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Faustwaffe\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nFeuer Artefakt Relikt Slot\nBlut Artefakt Relikt Slot\n\nKlassen: Druide\nAnlegen: Gewährt die Fähigkeit 'Zorn des Schläfers', die Euch durch den Avatar von Ursoc große Macht verleiht.\n\"Ursoc, Bruder des Ursol und Beschützer der Furbolgstämme... Träger der Kraft des Waldes selbst.\"\nVerkaufspreis:" }
entries[128822] = { ["name"] = "Ursocs Klauen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Faustwaffe\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Druide\n\"Azeroth wird Euch brauchen. Wenn Ihr nicht bereit seid, könnte die Welt fallen.\"\nVerkaufspreis:" }
entries[128823] = { ["name"] = "Die Silberne Hand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Streitkolben\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nHeilig Artefakt Relikt Slot\nLeben Artefakt Relikt Slot\n\nKlassen: Paladin\nAnlegen: Erhöht die Rüstung um 30%.\nAnlegen: Gewährt die Fähigkeit 'Tyrs Errettung', die Verbündete in der Nähe mit einer Heilungswelle überflutet. (Procchance: 6%)\n\"Tyr antwortete, dass er seine silberne Hand nicht als Zeichen seiner Niederlage ansah. Für ihn war es das Symbol seiner Aufopferung für die Verteidigung von Azeroth und er wollte, dass auch der Rest der Welt dies so sah.\"\nVerkaufspreis:" }
entries[128824] = { ["name"] = "Foliant der Silbernen Hand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n47 Rüstung\n+7 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Paladin\n\"Esarus thar no'Darador.\"\nVerkaufspreis:" }
entries[128825] = { ["name"] = "T'uure, Fanal der Naaru", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nHeilig Artefakt Relikt Slot\nLeben Artefakt Relikt Slot\n\nKlassen: Priester\nAnlegen: Eure Segenswörter haben eine Chance, ein Abbild von T'uure an Eurer Seite zu beschwören, das Euch im Kampf unterstützt.\n\"Gesegnet seien die Fackelträger, die Licht ins Dunkel bringen.\"\nVerkaufspreis:" }
entries[128826] = { ["name"] = "Thas'dorah, Erbstück von Haus Windläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDistanz Bogen\n3 - 5 Schaden Geschwindigkeit 3.00\n(1.3 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nSturm Artefakt Relikt Slot\nBlut Artefakt Relikt Slot\n\nKlassen: Jäger\nAnlegen: Gewährt Zugriff auf die Fähigkeit 'Windstoß', die dem Ziel massiven Schaden zufügt und die Bewegungsgeschwindigkeit aller Verbündeten auf der Flugbahn des Pfeils erhöht.\n\"Als er aus dem Sonnenbrunnen zurückgeholt wurde, strahlte der Bogen Macht aus. Talanas empfand große Ehre beim Anblick dieser Gabe. Er nannte die Waffe Thas'dorah: 'Ehre des Waldes'.\"\nVerkaufspreis:" }
entries[128827] = { ["name"] = "Xal'atath, Klinge des Schwarzen Imperiums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 Schaden Geschwindigkeit 1.80\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nSchatten Artefakt Relikt Slot\nBlut Artefakt Relikt Slot\n\nKlassen: Priester\nAnlegen: Gewährt die Fähigkeit 'Leerenstrom', die massiven Schattenschaden verursacht und Euren Abstieg aus dem Wahnsinn verlangsamt.\n\"Xal'atath hat ihren eigenen Kopf. Ignoriert ihr unerträgliches Flüstern. Glaubt niemals ihren Lügen. Nehmt, was Ihr von ihr braucht, aber denkt immer daran, dass die dunkle Präsenz in der Klinge nicht Eure Verbündete ist.\"\nVerkaufspreis:" }
entries[128831] = { ["name"] = "Kriegsklingen der Aldrachi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Dämonenjäger\n\"Seine Kriegsklingen heulten lauter als das Schlachtgetöse und zerrissen jeden, der ihnen nahekam. Jeder Dämon, den Toranaar bezwang, schien ihn mit neuer Lebenskraft und Stärke zu erfüllen. Er war eine Armee in sich selbst.\"" }
entries[128832] = { ["name"] = "Kriegsklingen der Aldrachi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nEisen Artefakt Relikt Slot\nArkan Artefakt Relikt Slot\n\nKlassen: Dämonenjäger\nAnlegen: Verleiht die Fähigkeit 'Seelenschnitzer', die Euer Ziel aufschlitzt, ihm Feuerschaden zufügt und ihm geringe Seelenfragmente entreißt.\n\"Die Aldrachi waren ein stolzes Volk. Zu stolz, um zu dienen. Millionen von Dämonen starben, bevor die Aldrachi ausgelöscht wurden, und nur Sargeras selbst vollbrachte es, ihren König zu töten.\"" }
entries[128833] = { ["name"] = "Ingwerwein der Kaldorei", ["text"] = "Benutzen: Ein ziemlich schwaches alkoholisches Getränk.\nVerkaufspreis:" }
