entries[128854] = { ["name"] = "Weglicht aus Helheim", ["text"] = "Questgegenstand" }
entries[128855] = { ["name"] = "Robuster Schild", ["text"] = "Questgegenstand\n\"Das Holz dieses Schilds ist noch nicht ganz verrottet, also sollte es noch ein paar Treffer aushalten können.\"" }
entries[128856] = { ["name"] = "Brauchbarer Speer", ["text"] = "Questgegenstand\n\"Er ist nicht mehr sonderlich scharf, aber wenigstens kommt es einem nicht so vor, als würde er gleich zerbrechen.\"" }
entries[128858] = { ["name"] = "Sichel von Elune", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nArkan Artefakt Relikt Slot\nLeben Artefakt Relikt Slot\n\nKlassen: Druide\nAnlegen: Gewährt den Zauber 'Neumond', der Schaden verursacht und dann in einen machtvolleren Zauber umgewandelt wird.\n\"Hierin steckt eine Kraft, die frei sein will. Durch Gleichgewicht und Beherrschung kann der Wolf gebändigt werden, doch nur für gewisse Zeit.\"\nVerkaufspreis:" }
entries[128859] = { ["name"] = "Fänge von Ashamane", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Druide\n\"Sie tobte durch die Reihen der Dämonen und verschwand dann zwischen den Bäumen. Sie verbarg sich in den Wipfeln und stürzte sich auf die Kommandanten der Legion. Sie war eine furchterregende Bestie. Sie kannte kein Halten, keine Gnade.\"\nVerkaufspreis:" }
entries[128860] = { ["name"] = "Fänge von Ashamane", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nFrost Artefakt Relikt Slot\nBlut Artefakt Relikt Slot\n\nKlassen: Druide\nAnlegen: Gewährt die Fähigkeit 'Ashamanes Raserei', die eine Reihe blutiger Angriffe auf ein gegnerisches Ziel entfesselt.\n\"Ashamanes Opfer wird bis heute gedacht. Wir leben durch ihre Gnade und ihre Kinder durchstreifen als treue Begleiter noch immer mit uns die Wälder.\"\nVerkaufspreis:" }
entries[128861] = { ["name"] = "Titanenblitz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDistanz Schusswaffe\n3 - 6 Schaden Geschwindigkeit 3.00\n(1.5 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nSturm Artefakt Relikt Slot\nArkan Artefakt Relikt Slot\n\nKlassen: Jäger\nAnlegen: Hati kämpft jetzt als Begleiter für Euch.\n\"Ein unnachahmliches Beispiel technomagischer Ingenieurskunst, erfüllt mit der Macht der Stürme.\"\nVerkaufspreis:" }
entries[128862] = { ["name"] = "Schwarzfrost", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nFrost Artefakt Relikt Slot\nArkan Artefakt Relikt Slot\n\nKlassen: Magier\nAnlegen: Gewährt die Fähigkeit 'Schwarzblitz', die einem Einzelziel massiven Schattenfrostschaden zufügt.\n\"Schwarzfrost enthielt nur einen kleinen Teil von Alodis Macht, doch selbst das war mehr, als die meisten Magi je zu beherrschen hoffen durften.\"\nVerkaufspreis:" }
entries[128864] = { ["name"] = "Die steinigen Hügel des Hochbergs", ["text"] = "Questgegenstand\n\"Die Tinte ist durch Ziegenspeichel verlaufen und unscharf.\"" }
entries[128866] = { ["name"] = "Der Wahrheitshüter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n25 Rüstung\n+1 Stärke\n+3 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nHeilig Artefakt Relikt Slot\nEisen Artefakt Relikt Slot\n\nKlassen: Paladin\nAnlegen: Gewährt die Fähigkeit 'Auge von Tyr', die einen Lichtblitz aus Eurem Schild hervorruft, der Gegner in der Nähe schwächt.\n\"Als der Hammer das erste Mal fiel, entsprangen Flüsse aus Magma aus dem Eis. Beim zweiten Mal heulte der Himmel auf und Blitze entflammten ihn. Beim dritten Mal drang ein Sonnenstrahl durch den Sturm und flüsterte über die Oberfläche des Wahrheitshüters.\"\nVerkaufspreis:" }
entries[128867] = { ["name"] = "Eidsucher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Paladin\n\"Töten um des Tötens willen... Erobern um der Eroberung willen... Es liegt keine Ehre in solchen Dingen. Nur Schande und Bedauern.\"\nVerkaufspreis:" }
entries[128868] = { ["name"] = "Zorn des Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nHeilig Artefakt Relikt Slot\nSchatten Artefakt Relikt Slot\n\nKlassen: Priester\nAnlegen: Gewährt die Fähigkeit 'Zorn des Lichts', die einen Strom heiligen Feuers auf einen Gegner niedergehen lässt. (Procchance: 15%)\n\"Wir wohnten an diesem Tag voller Hoffnung und Hingabe der Zeremonie bei... und verließen sie voller Kummer.\"\nVerkaufspreis:" }
entries[128869] = { ["name"] = "Die Königsmörder", ["text"] = "Kummer\nWird beim Aufheben gebunden\nEinzigartig\nSchildhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schurke\n\"Es war kein angenehmer Tod. Doch er war schnell, lautlos und effizient. Als der Orc seinen letzten Atemzug tat, verzerrte dies die tödliche Wunde. Niemand konnte sagen, ob er einem Messer, einer Axt oder einem Speer erlegen war.\"\nVerkaufspreis:" }
entries[128870] = { ["name"] = "Die Königsmörder", ["text"] = "Qual\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nSchatten Artefakt Relikt Slot\nEisen Artefakt Relikt Slot\n\nKlassen: Schurke\nAnlegen: Gewährt Euch die Fähigkeit 'Königsmord', die Eurem Ziel ein Gift von unerreichter Potenz injiziert.\n\"Unzählige Stimmen wurden zum Schweigen gebracht, unzählige Anführer gestürzt... alles auf sein launisches, finsteres Geheiß. Für diese Taten würde es keine Wiedergutmachung geben, nur Einsamkeit und Kummer.\"\nVerkaufspreis:" }
entries[128872] = { ["name"] = "Die Schreckensklingen", ["text"] = "Schicksal\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nBlut Artefakt Relikt Slot\nEisen Artefakt Relikt Slot\n\nKlassen: Schurke\nAnlegen: Gewährt die Fähigkeit 'Fluch der Schreckensklingen', durch die Ihr Finishing-Moves schneller einsetzen könnt... dafür jedoch einen Preis zahlt.\n\"Sie sah sich selbst, wie sie eine riesige Piratenflotte kommandierte, eine, die die See beherrschen und ganz Azeroth unterwerfen konnte. Jeder, der es wagte, sie herauszufordern, wurde verbrannt und jede Stadt, die an ihren Schätzen festhielt, vernichtet.\"\nVerkaufspreis:" }
entries[128873] = { ["name"] = "Zorn der Steinmutter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schamane\n\"Erschaffen durch die Macht des Schicksalshammers und des Schamanen, der diesen trägt.\"\nVerkaufspreis:" }
entries[128874] = { ["name"] = "Ein winziges Vogelscheuchenkostüm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Nach seiner Beschwörung ist Pepe manchmal als Vogelscheuche verkleidet." }
entries[128875] = { ["name"] = "Faules Rippchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bloß nicht! Es ist verdorben! (3 Sek. Abklingzeit)\n\"Die Maden haben übrig gelassen, was sie nicht mehr verzehren konnten.\"" }
