entries[128908] = { ["name"] = "Kriegsschwerter der Valarjar", ["text"] = "Odyns Zorn\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nFeuer Artefakt Relikt Slot\nSturm Artefakt Relikt Slot\n\nKlassen: Krieger\nAnlegen: Gewährt die Fähigkeit 'Odyns Zorn', die Gegnern in der Nähe massiven Feuerschaden zufügt.\n\"Helyas Verrat wird nie vergeben werden. Lasst sie unter den Wellen verrotten, fern der Hallen der Tapferkeit.\"\nVerkaufspreis:" }
entries[128910] = { ["name"] = "Strom'kar der Kriegsbrecher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nEisen Artefakt Relikt Slot\nBlut Artefakt Relikt Slot\n\nKlassen: Krieger\nAnlegen: Gewährt die Fähigkeit 'Kriegsbrecher', die in einem Bereich massiven Schaden verursacht und Gegner verwundbar macht.\n\"Der letzte Schlag wird durch den Stahl des barbarischen Königs erfolgen. Mit ihm wird das Getöse der Schlacht verstummen und für das erste Königreich wird ein neues Zeitalter des Friedens beginnen.\"\nVerkaufspreis:" }
entries[128911] = { ["name"] = "Sharas'dal, Szepter der Gezeiten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Streitkolben\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nLeben Artefakt Relikt Slot\nFrost Artefakt Relikt Slot\n\nKlassen: Schamane\nAnlegen: Gewährt die Fähigkeit 'Gabe der Königin', die Eure Verbündeten um einen großen Betrag heilt und ihre maximale Gesundheit erhöht.\n\"Sie trieben den Abgrund hinab, doch Azshara und ihre Hochgeborenen blieben ungebrochen. Sie waren von absoluter Dunkelheit umgeben, und die Königin zwang Sharas'dal, ihnen das Licht zu bringen...\"\nVerkaufspreis:" }
entries[128912] = { ["name"] = "Seuchenprobe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[128921] = { ["name"] = "Zauberschlacke", ["text"] = "Questgegenstand\n\"Die angesammelte Schlacke einer Stadt voller Magier.\"" }
entries[128922] = { ["name"] = "Alchemistische Flamme", ["text"] = "Questgegenstand\n\"Unter Alchemisten umgangssprachlich 'flüssiges Feuer' genannt.\"" }
entries[128923] = { ["name"] = "Bezauberte Isolierung", ["text"] = "Questgegenstand\n\"Speziell verarbeitet, um sowohl gegen Hitze als auch Leyenergie zu schützen.\"" }
entries[128924] = { ["name"] = "Stillgelegte Heizung", ["text"] = "Questgegenstand\n\"Eher mechanisch denn magisch. Möglicherweise stammt sie aus dem Ingenieursladen?\"" }
entries[128933] = { ["name"] = "Rashars rechtes Auge", ["text"] = "Questgegenstand\n\"Das bernsteinfarbene Auge hat einen weichen, warmen Schimmer, der zu einem genaueren Blick einlädt.\"" }
entries[128934] = { ["name"] = "Schild der Meereskönigin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n25 Rüstung\n+1 Stärke\n+3 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schamane\n\"Als der Ozean das Leben aus ihren Körpern schmetterte, regten sich uralte Kreaturen in der Dunkelheit. Ihr Flüstern floss durch die Strömung. Ihre Macht legte sich eng um die Königin und ihre Diener.\"\nVerkaufspreis:" }
entries[128935] = { ["name"] = "Die Faust des Ra-den", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Faustwaffe\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nSturm Artefakt Relikt Slot\nFrost Artefakt Relikt Slot\n\nKlassen: Schamane\nAnlegen: Gewährt die Fähigkeit 'Sturmhüter', die Euren 'Blitzschlag' oder 'Kettenblitzschlag' mit großer Macht erfüllt.\n\"Um Al'Akirs Untergang zu besiegeln, donnerte Meister Ra seine Faust in den Gipfel des Berges. Der Himmel brach auf und all das Feuer und der Zorn darin stürzte hinab auf den Windlord.\"\nVerkaufspreis:" }
entries[128936] = { ["name"] = "Schutz des hohen Hüters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n25 Rüstung\n+1 Stärke\n+3 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schamane\n\"Ra und Helya erschufen einen Schild, den Schutz des hohen Hüters, als Schlüssel für die Elementarebene. Er pulsierte mit der Energie der vier Elemente, die Ra nach Belieben rufen konnte.\"\nVerkaufspreis:" }
entries[128937] = { ["name"] = "Sheilun, Stab der Nebel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nFrost Artefakt Relikt Slot\nLeben Artefakt Relikt Slot\n\nKlassen: Mönch\nAnlegen: Gewährt Euch den Zauber 'Sheiluns Gabe', der einen Verbündeten um einen beträchtlichen Wert heilt.\n\"Ihr sucht die ruhige, unausweichliche Macht eines tiefen Flusses, der Schluchten in den stärksten Stein schneidet und Krieger mit seinen Strömungen ohne das leiseste Kräuseln hinfortträgt. Sheilun ist die Verkörperung dieses Konzepts.\"\nVerkaufspreis:" }
entries[128938] = { ["name"] = "Fu Zan, Gefährte des Wanderers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nLeben Artefakt Relikt Slot\nSturm Artefakt Relikt Slot\n\nKlassen: Mönch\nAnlegen: Gewährt die Fähigkeit 'Explodierendes Fässchen', die genau das tut, was Ihr glaubt, dass sie es tut.\n\"Von Anfang an hat dieser Stab legendäre Wesen und unsterbliche Geister begleitet, während sie wichtige Arbeiten in ganz Azeroth ausführten.\"\nVerkaufspreis:" }
entries[128940] = { ["name"] = "Fäuste der Himmel", ["text"] = "Al'burq\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Faustwaffe\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nSturm Artefakt Relikt Slot\nEisen Artefakt Relikt Slot\n\nKlassen: Mönch\nAnlegen: Gewährt die Fähigkeit 'Schlag des Windlords', die einen heftigen Doppelangriff hervorruft, der Euren Gegner zusätzlich verkrüppelt.\n\"Als Irmaat seine zwei Waffen erhob und die Macht in ihnen auf die Probe stellte, entsprang daraus unkontrollierbare Wut.\"\nVerkaufspreis:" }
entries[128941] = { ["name"] = "Szepter des Sargeras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nTeufel Artefakt Relikt Slot\nFeuer Artefakt Relikt Slot\n\nKlassen: Hexenmeister\nAnlegen: Gewährt die Fähigkeit 'Dimensionsriss', die Portale in Raum und Zeit aufreißt und vernichtenden Schaden gegen Eure Gegner freisetzt.\n\"Als schließlich der Moment kam, in dem Ner'zhul zum Handeln gezwungen war, tat er es ganz hemmungslos und dachte dabei nicht an Konsequenzen. Die Vernichtung von Draenor war ihm egal, er hieß sie sogar als Teil seines Vermächtnisses willkommen.\"\nVerkaufspreis:" }
entries[128942] = { ["name"] = "Ulthalesh, Sense der Totenwinde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nSchatten Artefakt Relikt Slot\nBlut Artefakt Relikt Slot\n\nKlassen: Hexenmeister\nAnlegen: Gewährt die Fähigkeit 'Seelen ernten', die die Seelen gefallener Gegner erntet, um Ulthalesh mit Macht zu erfüllen.\n\"Der Meister der Sichel wird entweder Sataiel besiegen oder verschlungen werden, was die Klinge nur noch stärker machen wird. Danach wird ein anderer kommen, um seinen Platz einzunehmen. Und danach wieder ein anderer.\"\nVerkaufspreis:" }
entries[128943] = { ["name"] = "Schädel der Man'ari", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nIn Schildhand geführt\n+3 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nSchatten Artefakt Relikt Slot\nFeuer Artefakt Relikt Slot\n\nKlassen: Hexenmeister\nAnlegen: Gewährt die Fähigkeit 'Thal'kiels Verzehr', durch die Thal'kiel gerufen wird, um einen Gegner zu quälen.\n\"Als Thal'kiel endlich erschien, war er verändert. Um Jahrhunderte gealtert, allein in der Dunkelheit mit seinen Gedanken und Sklaven. Er war buckelig und hatte ein merkwürdiges Glänzen in den Augen. Er beschwor seine Erwecker und wir antworteten ihm...\"\nVerkaufspreis:" }
