entries[129177] = { ["name"] = "Modrige Tarotkarte", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine alte Tarotkarte. Die Ränder sind schon ziemlich angefressen, doch im Licht sieht man ihren noch verbliebenen magischen Schimmer.\"" }
