entries[129179] = { ["name"] = "Soldatenfutter", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und werdet außerhalb des Kampfes 1 Stunde lang alle 5 Sek. um 112 Gesundheit geheilt.\n\" Für überragende Kampfkraft und glänzendes Fell. \"\nVerkaufspreis:" }
entries[129181] = { ["name"] = "Kriegsgleve der Illidari", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Kriegsgleve\n5 - 8 Schaden Geschwindigkeit 2.60\n(2.5 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 85 / 85\nKlassen: Dämonenjäger\nRächer der Illidari (0/2)\nKriegsgleve der Illidari\nKriegsgleve der Illidari\n(2) Set : Erhöht die Angriffskraft im Kampf gegen Dämonen um 30 .\nVerkaufspreis:" }
