entries[129204] = { ["name"] = "Phiole mit Teufelsseelenblut", ["text"] = "Questgegenstand\nEinzigartig (25)\nBenutzen: Fügt 25 Phiolen mit Teufelsseelenblut und 1 Blut von Sargeras zusammen, um eine Teufelsseelentinte zu erschaffen." }
