entries[129210] = { ["name"] = "Teufelskristallfragmente", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerschmettert die Kristalle für eine Chance, bei Treffern Feuerschaden zu verursachen und Eure Bewegungsgeschwindigkeit 10 Min. lang um 10% zu erhöhen.\nKann nur in Mardum und im Verlies der Wächterinnen eingesetzt werden. (Procchance: 30%, 1s Abklingzeit) (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[129211] = { ["name"] = "Schlüpfriges Romantikschmökerset", ["text"] = "Spielzeug\nBenutzen: Schreibt einen schlüpfrigen Romantikschmöker. (20 Min Abklingzeit)" }
entries[129212] = { ["name"] = "Ryno Blumenfelds Analyse", ["text"] = "Questgegenstand\n\"Eine Reihe detaillierter Aufzeichnungen darüber, wo Teufelswurz wachsen könnte.\"" }
