entries[129215] = { ["name"] = "Pulsierender Ring des bebenden Zorns", ["text"] = "Questgegenstand\n\"Dieser von Dryaden gefertigte Ring schäumt von dem Hass und Zorn, den er den Harpyien von Thas'talah entzogen hat, geradezu über.\"" }
