entries[129279] = { ["name"] = "Verzauberte Steinpfeife", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört den an die verzauberte Steinpfeife gebundenen Sandpfeifer. (1 Min Abklingzeit)\nBenötigt Farondis' Hofstaat\n- Wohlwollend\n\"Wurde speziell für den jungen Prinzen Farondis angefertigt, als sein geliebtes Haustier aus Kindertagen verstarb.\"\nVerkaufspreis:" }
entries[129280] = { ["name"] = "Zügel des prestigeträchtigen Schlachtrosses", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares boshaftes schwarzes Schlachtross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Gerüstet, um Zusammenstöße im Kampf auszuhalten.\"\nErfolg:\nJeder gegen jeden und alle für mich" }
entries[129283] = { ["name"] = "Gesuch der Illidari", ["text"] = "Questgegenstand\n\"Ich, Allari die Seelenfresserin, erbitte hiermit in aller Form die Unterstützung von Erzmagier Sternensinger im Kampf gegen die Legion.\"" }
